-- Fixture independente de autorização. Migrations reais são validadas no BANCO.
CREATE TABLE roles(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(50) UNIQUE NOT NULL, description text, created_at timestamp DEFAULT current_timestamp);
CREATE TABLE users(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, role_id integer REFERENCES roles, name varchar(150), active boolean DEFAULT true, created_at timestamp DEFAULT current_timestamp);
CREATE TABLE credentials(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id integer UNIQUE REFERENCES users ON DELETE CASCADE, email varchar(150) UNIQUE, password_hash text);
CREATE TABLE permissions(code varchar(100) PRIMARY KEY, description text);
CREATE TABLE role_permissions(role_id integer REFERENCES roles, permission_code varchar(100) REFERENCES permissions, PRIMARY KEY(role_id,permission_code));
CREATE TABLE properties(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(100), owner_user_id integer REFERENCES users, location text, created_at timestamp DEFAULT current_timestamp);
CREATE TABLE user_properties(user_id integer REFERENCES users ON DELETE CASCADE, property_id integer REFERENCES properties ON DELETE CASCADE, PRIMARY KEY(user_id,property_id));
CREATE TABLE stations(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, property_id integer REFERENCES properties, name text, mac_address text UNIQUE, latitude numeric DEFAULT -23, longitude numeric DEFAULT -45, last_communication_at timestamp DEFAULT current_timestamp, created_at timestamp DEFAULT current_timestamp, collection_interval_seconds integer DEFAULT 60);
CREATE TABLE sensor_types(id integer PRIMARY KEY, name text, unit_of_measure text, factor numeric, gain numeric, offset_value numeric);
CREATE TABLE sensors(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, station_id integer REFERENCES stations, sensor_type_id integer REFERENCES sensor_types, local_identifier text, operational_status boolean DEFAULT true, min_value numeric, max_value numeric, gain numeric, offset_value numeric, model text, created_at timestamp DEFAULT current_timestamp);
CREATE TABLE readings(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sensor_id integer REFERENCES sensors, value numeric, unix_time bigint, data_consistent boolean DEFAULT true, created_at timestamp DEFAULT current_timestamp);
CREATE TABLE alert_configs(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, manager_user_id integer REFERENCES users, sensor_id integer REFERENCES sensors, reference_value numeric, comparison_operator varchar(2), message text, active boolean DEFAULT true, created_at timestamp DEFAULT current_timestamp);
CREATE TABLE triggered_alerts(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, alert_config_id integer REFERENCES alert_configs, reading_id bigint REFERENCES readings, acknowledged_by integer REFERENCES users, triggered_at timestamp DEFAULT current_timestamp, acknowledged_at timestamp);
CREATE TABLE occurrences(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, type text, status text DEFAULT 'OPEN', station_id integer REFERENCES stations, sensor_id integer REFERENCES sensors, reading_id bigint REFERENCES readings, value numeric, description text, detected_at timestamp DEFAULT current_timestamp, resolved_at timestamp);
